const digits=x=>String(x||'').replace(/\D/g,'');
function normalizedKey(s){let key=String(s||'').trim();if(/%[0-9a-fA-F]{2}/.test(key)){try{key=decodeURIComponent(key)}catch{}}return key}
function xmlTag(raw,name){const m=raw.match(new RegExp('<(?:[\\w.-]+:)?'+name+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:[\\w.-]+:)?'+name+'>','i'));return m?m[1].trim():''}
